import math

def eulerian_num(n, m):
    """
    Calculate the Eulerian number A(n, m).

    Parameters:
    - n: An integer, the number of elements in the set.
    - m: An integer, the number of fixed points in the permutation.

    Returns:
    - The Eulerian number A(n, m).
    """
    if n < 0 or m < 0:
        raise ValueError("n and m must be non-negative integers.")

    if m > n:
        return 0

    def factorial(n):
        return math.factorial(n)

    def binomial(n, k):
        return int(factorial(n) / (factorial(k) * factorial(n - k)))

    # Calculate the Eulerian number using the formula:
    # A(n, m) = (n - 1) * A(n - 1, m - 1) + A(n - 1, m)
    # Base cases:
    if m == 0:
        return factorial(n - 1)
    elif m == n - 1:
        return factorial(n - 1)
    elif m == n:
        return 0
    else:
        return (n - 1) * eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m)

    # If the value is not calculated, use the binomial coefficient formula:
    if m == 0:
        return binomial(n - 1, 1) * (n - 2)
    elif m == n - 1:
        return binomial(n - 1, 1) * (n - 2)
    else:
        return binomial(n - 1, m + 1) - binomial(n - 1, m)

